const DEVICE    = env.get('DEVICE');
let   count     = flow.get('nullCount')  || 0;
let   isOffline = flow.get('isOffline')  || false;
const value     = msg.payload?.value;

if (value === null || value === undefined) {
    count++;
    flow.set('nullCount', count);
    if (count >= 3 && !isOffline) {
        flow.set('isOffline', true);
        return { payload: { device: DEVICE, status: 'offline' } };
    }
    return null;
}

flow.set('nullCount', 0);
if (isOffline) {
    flow.set('isOffline', false);
    return { payload: { device: DEVICE, status: 'online' } };
}
return null;

const type  = msg.payload.type;
const value = msg.payload.value;
const time  = msg.payload.time || Date.now();

if (type === undefined || value === undefined) return null;

let buf = global.get('aiBuffer') || {};
if (!buf[type]) buf[type] = [];

buf[type].push({ value, time });

if (buf[type].length > 120) buf[type].shift();

global.set('aiBuffer', buf);

return msg;

const valueField = env.get('VALUE_FIELD');
const device     = env.get('DEVICE');
const type       = env.get('TYPE');
const diffThresh = Number(env.get('DIFF_THRESHOLD'));
const flowKey    = env.get('FLOW_KEY');

if (typeof msg.payload === 'string') {
    try { msg.payload = JSON.parse(msg.payload); }
    catch(e) { node.warn('Invalid JSON'); return null; }
}

const value = msg.payload[valueField];
if (value === undefined || value === null) {
    node.warn(type + ': value field missing');
    return null;
}

const reading = { device, type, value, time: Date.now() };

global.set(type + '_lastReading', reading);

let buf = global.get('aiBuffer') || {};
if (!buf[type]) buf[type] = [];
buf[type].push({ value, time: reading.time });
if (buf[type].length > 120) buf[type].shift();
global.set('aiBuffer', buf);

const lastValue  = flow.get(flowKey);
const shouldSend = (lastValue === undefined || lastValue === null)
                || (Math.abs(value - lastValue) >= diffThresh);
if (shouldSend) flow.set(flowKey, value);

msg.reading    = reading;
msg.shouldSend = shouldSend;
msg.payload    = reading;
return msg;

const dangerThresh = flow.get('dynamicDangerThreshold')
               ?? Number(env.get('DANGER_THRESHOLD'));
const actuatorKey  = env.get('ACTUATOR_STATE_KEY');

const newState     = msg.reading.value > dangerThresh ? 'ON' : 'OFF';
const currentState = flow.get(actuatorKey);
const stateChanged = currentState !== newState;

if (stateChanged) flow.set(actuatorKey, newState);

msg.newActuatorState = newState;
msg.actuatorChanged  = stateChanged;
return msg;

const readingMsg  = { payload: msg.reading };
const httpMsg     = msg.shouldSend
    ? { payload: msg.reading, headers: { 'Content-Type': 'application/json' } }
    : null;
const actuatorMsg = msg.actuatorChanged
    ? { payload: { set_controller: msg.newActuatorState } }
    : null;
return [readingMsg, httpMsg, actuatorMsg];

const isOn = (msg.payload.set === "on");
const status = isOn ? 'online' : 'offline';
const device = env.get("deviceName");
const message = env.get("logMessage");

const logMessage = (message != "") ? message : `${device} ${status}`;

// HTTP Request node 1
let msg1 = {
    payload: {
        device: device,
        status: status
    }
};

// HTTP Request node 2
let msg2 = {
    payload: {
        device: device,
        message: logMessage
    }
};

return [msg1, msg2];

const buf = global.get('aiBuffer') || {};

function stats(arr) {
    if (!arr || arr.length === 0) return {};
    const vals = arr.map(r => r.value);
    const avg  = vals.reduce((a, b) => a + b, 0) / vals.length;
    const min  = Math.min(...vals);
    const max  = Math.max(...vals);
    const std  = Math.sqrt(vals.reduce((a, b) => a + Math.pow(b - avg, 2), 0) / vals.length);
    const span = arr.length > 1 ? (arr[arr.length - 1].time - arr[0].time) / 1000 : 60;
    const roc  = arr.length > 1 ? (vals[vals.length - 1] - vals[0]) / span : 0;
    return {
        avg:   +avg.toFixed(3),
        min:   +min.toFixed(3),
        max:   +max.toFixed(3),
        std:   +std.toFixed(3),
        roc:   +roc.toFixed(5),
        count: vals.length
    };
}

const temp     = stats(buf['temperature']);
const humidity = stats(buf['humidity']);
const mq2      = stats(buf['gas']);
const flames   = buf['flame'] || [];
const flameTriggers = flames.filter(r => Number(r.value) > 0).length;

const payload = {
    timestamp:        new Date().toISOString(),
    window_seconds:   60,
    temp_avg:         temp.avg      ?? null,
    temp_min:         temp.min      ?? null,
    temp_max:         temp.max      ?? null,
    temp_std:         temp.std      ?? null,
    temp_roc:         temp.roc      ?? null,
    humidity_avg:     humidity.avg  ?? null,
    humidity_min:     humidity.min  ?? null,
    humidity_max:     humidity.max  ?? null,
    humidity_std:     humidity.std  ?? null,
    mq2_avg:          mq2.avg       ?? null,
    mq2_min:          mq2.min       ?? null,
    mq2_max:          mq2.max       ?? null,
    mq2_std:          mq2.std       ?? null,
    mq2_roc:          mq2.roc       ?? null,
    flame_triggered:  flameTriggers > 0,
    flame_count:      flameTriggers,
    sample_count:     Math.max(temp.count||0, humidity.count||0, mq2.count||0, flames.length)
};

global.set('aiBuffer', {});

msg.payload = payload;
msg.headers = { 'Content-Type': 'application/json' };
return msg;

msg.payload = { message: 'MQ2 sensor detected high gas/smoke level', type: 'ALARM' };
msg.headers = { 'Content-Type': 'application/json' };
return msg;

let data = msg.payload;
if (typeof data === 'string') {
    try { data = JSON.parse(data); } catch(e) { data = { value: Number(data) }; }
}
if (typeof data === 'number') data = { value: data };

let buf = global.get('aiBuffer') || {};
if (!buf['flame']) buf['flame'] = [];
buf['flame'].push({ value: Number(data?.value) || 0, time: Date.now() });
if (buf['flame'].length > 120) buf['flame'].shift();
global.set('aiBuffer', buf);

const flameValue = Number(data?.value);
if (Number.isNaN(flameValue)) return null;

const lastValue = flow.get('lastFlameValue');
flow.set('lastFlameValue', flameValue);

if (flameValue === 1 && flameValue !== lastValue) {
    const notifyMsg = {
        payload: { message: 'Flame sensor detected fire!', type: 'ALARM' },
        headers: { 'Content-Type': 'application/json' }
    };
    const alarmMsg  = { payload: { set_controller: 'ON' } };
    return [notifyMsg, alarmMsg];
}
return [null, null];

const sensors = ['temperature', 'humidity', 'gas'];
const msgs    = [];
for (const s of sensors) {
    const r = global.get(s + '_lastReading');
    if (r) msgs.push({
        payload: r,
        headers: { 'Content-Type': 'application/json' }
    });
}
return [msgs];

const status = (msg.payload.set === "on")
msg.payload = status;
return msg ;

